WITH RecursiveTagQuestions AS (
    -- Recursive to explore posts excelling in tags nesting or iteration simulation
    SELECT 
        p.Id,
        p.Title,
        string_to_array(substring(p.Tags, 2, length(p.Tags)-2), '><') AS TagNames,
        p.OwnerUserId,
        p.CreationDate
    FROM Posts p
    WHERE p.PostTypeId = 1 -- Questions only
      AND p.Tags IS NOT NULL
      AND p.Score > 10
    UNION ALL
    SELECT 
        rq.Id,
        rq.Title || ' && ' || dist.TagsAggicator,
        dist.TagsArr,
        rq.OwnerUserId,
        rq.CreationDate
    FROM RecursiveTagQuestions rq
